local locale = type(GetLocale) == "function" and GetLocale() or "enUS"
function ns.L(text)
    if locale == "ruRU" then
        local value = RU[text] or RU_HELP[text]
        if value then return value end
        local lowerInitial = text and text:sub(1, 1):lower() .. text:sub(2)
        return RU[lowerInitial] or text
    end
    return text
end
